'use strict';
function auditStoryProject(p=project){const issues=[],clips=new Map((p.audioClips||[]).map(c=>[c.id,c])),add=(severity,message,s,extra={})=>issues.push({severity,message,sceneId:s?.id,...extra});let offset=0;for(const s of p.scenes){const lines=storyLines(s),objects=new Map(s.objects.map(o=>[o.id,o]));if(lines.length&&!s.dialogueArranged)add('warning','Arrange voices to synchronize the script and timeline.',s,{action:'script'});const lastBySpeaker=new Map();for(const line of [...lines].sort((a,b)=>a.start-b.start)){const actor=objects.get(line.speakerId),clip=clips.get(line.audioId),at=line.start,extra={at,lineId:line.id,objectId:actor?.id,action:'script'};if(line.speakerId&&!actor)add('error','A dialogue speaker is missing from the scene.',s,extra);if(line.text.trim()&&!line.audioId)add('warning','This line has no voice recording: '+line.text.slice(0,90),s,extra);if(line.audioId&&!clip)add('error','A line refers to a missing voice clip.',s,extra);if(at<0||at+line.duration>s.duration+.001)add('error','A dialogue line extends outside its scene.',s,extra);if(clip){if(Math.abs(clip.start-(offset+at))>1/30)add('warning','A voice clip does not start with its script line.',s,extra);if(Math.abs(clip.duration-line.duration)>.15)add('warning','A line and its voice have different lengths.',s,extra);if(!clip.src)add('error','A voice recording has no source media.',s,extra);if(actor?.type==='puppet'&&!actor.mouth)add('warning','Set a mouth area on '+actor.name+' for visible lip-sync.',s,{...extra,action:'mouth'});if(actor&&(!clip.mouthCues?.length||!actor.lipSync))add('warning','Review lip-sync for '+actor.name+': mouth cues or playback are missing.',s,extra);const pace=textWords(line.text).length/Math.max(.1,clip.duration);if(pace>5.5)add('warning','This line is fast. Review its voice pace and readability.',s,extra)}if(line.speakerId&&clip){const previous=lastBySpeaker.get(line.speakerId);if(previous&&at<previous.start+previous.duration-.001)add('error',actorName(s,line.speakerId)+' has overlapping voice lines.',s,extra);if(!previous||line.start+line.duration>previous.start+previous.duration)lastBySpeaker.set(line.speakerId,line)}}for(let i=1;i<lines.length;i++){const before=lines[i-1],after=lines[i],gap=after.start-before.start-before.duration;if(gap>4)add('info','A '+gap.toFixed(1)+' second dialogue gap may need a pacing review.',s,{at:before.start+before.duration,action:'script',lineId:after.id})}for(const o of s.objects){if(o.exitTransition){const next=objects.get(o.exitTransition.toId);if(!next||Math.abs(clipEnd(o,s)-clipStart(next))>.05)add('warning','The transition after '+o.name+' is inactive because its clips are not adjacent.',s,{at:clipEnd(o,s),objectId:o.id,action:'effects'})}if(o.type==='puppet'&&o.lipSync&&!o.mouth&&!lines.some(l=>l.speakerId===o.id))add('warning','Set a mouth area on '+o.name+' before using lip-sync.',s,{at:0,objectId:o.id,action:'mouth'})}for(const event of s.propInteractions||[])if([event.actorId,event.propId,...(event.otherId?[event.otherId]:[])].some(id=>!objects.has(id)))add('error','An object interaction refers to a missing layer.',s,{at:event.start});if(['crossfade','slide-left','slide-right','zoom','match'].includes(s.transition)&&s===p.scenes.at(-1))add('warning','This final scene has a transition that needs a following scene.',s,{at:s.duration});offset+=s.duration}if(!valid(p))add('error','The project contains invalid timing or metadata. Save a backup and review recent edits.');return issues}
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openStoryAudit">Check storyboard</button>');$('storyboardDialog').querySelector('.tool-row').append(Object.assign(document.createElement('button'),{id:'auditFromStoryboard',textContent:'Check story'}));$('cancelExport').before(Object.assign(document.createElement('button'),{id:'auditBeforeExport',textContent:'Check story'}));
document.body.insertAdjacentHTML('beforeend','<dialog id="storyAuditDialog"><div class="tool-heading"><h2>Storyboard checks</h2><button id="closeStoryAudit">Close</button></div><p class="note">Review missing voices, mouth setup and timing before export. These checks help you review the story; intentional silent scenes and pauses are allowed.</p><p id="storyAuditSummary" class="analysis-summary"></p><button id="refreshStoryAudit">Run checks again</button><div id="storyAuditIssues" class="ease-card-list"></div></dialog>');
function openAuditIssue(issue){$('storyAuditDialog').close();const index=project.scenes.findIndex(s=>s.id===issue.sceneId);if(index<0)return;sceneIndex=index;time=clamp(issue.at||0,0,current().duration);selectLayers(issue.objectId&&current().objects.some(o=>o.id===issue.objectId)?[issue.objectId]:[]);selectedDialogueId=issue.lineId||null;render();if(issue.action==='mouth'&&object()?.type==='puppet')openImageRig(object(),true);else if(issue.action==='script')$('openStoryTools').onclick();else if(issue.action==='effects')$('openClipEffects').onclick()}
function renderStoryAudit(){const issues=auditStoryProject(),list=$('storyAuditIssues');list.replaceChildren();$('storyAuditSummary').textContent=issues.length?issues.filter(i=>i.severity==='error').length+' errors · '+issues.filter(i=>i.severity==='warning').length+' checks to review · '+issues.filter(i=>i.severity==='info').length+' pacing notes':'No voice, mouth-setup or timing issues found.';for(const issue of issues){const row=document.createElement('article');row.className='ease-entry story-audit-'+issue.severity;const text=document.createElement('span');text.textContent=(project.scenes.find(s=>s.id===issue.sceneId)?.name||'Project')+' · '+issue.message;row.append(text);if(issue.sceneId)row.append(storyButton(issue.action==='mouth'?'Set mouth':issue.action==='script'?'Edit script':'Open scene',()=>openAuditIssue(issue)));list.append(row)}}
function openStoryAudit(){stop();for(const id of ['exportDialog','storyboardDialog'])if($(id).open)$(id).close();renderStoryAudit();$('storyAuditDialog').showModal()}
$('openStoryAudit').onclick=openStoryAudit;$('auditFromStoryboard').onclick=openStoryAudit;$('auditBeforeExport').onclick=openStoryAudit;$('refreshStoryAudit').onclick=renderStoryAudit;$('closeStoryAudit').onclick=()=>$('storyAuditDialog').close();
